with open(ALL_LISTINGS_FILE, "r", encoding="utf-8", errors="ignore") as f:
    all_rows = list(csv.DictReader(f, delimiter="\t"))

by_asin = {}
by_sku = {}
for r in all_rows:
    by_asin.setdefault(r["asin1"], []).append(r)
    by_sku[r["seller-sku"]] = r

fba_by_sku = {}
